CREATE TYPE "Role" AS ENUM ('USER','ORGANIZER','ADMIN');
CREATE TYPE "EventStatus" AS ENUM ('DRAFT','PENDING_APPROVAL','PUBLISHED','REJECTED','CANCELLED','COMPLETED');
CREATE TYPE "BookingStatus" AS ENUM ('CONFIRMED','CANCELLED','REFUNDED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'USER',"isBlocked" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Event" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"venue" TEXT NOT NULL,"city" TEXT NOT NULL,"eventDate" TIMESTAMP(3) NOT NULL,"startTime" TEXT NOT NULL,"endTime" TEXT NOT NULL,"ticketPrice" DECIMAL(10,2) NOT NULL,"totalSeats" INTEGER NOT NULL,"availableSeats" INTEGER NOT NULL,"imageUrl" TEXT,"organizerId" TEXT NOT NULL,"status" "EventStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Event_organizerId_fkey" FOREIGN KEY ("organizerId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE "Booking" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"pricePerTicket" DECIMAL(10,2) NOT NULL,"totalAmount" DECIMAL(10,2) NOT NULL,"status" "BookingStatus" NOT NULL DEFAULT 'CONFIRMED',"bookingReference" TEXT NOT NULL UNIQUE,"bookedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"cancelledAt" TIMESTAMP(3),CONSTRAINT "Booking_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT,CONSTRAINT "Booking_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE RESTRICT);
CREATE TABLE "RefreshToken" ("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "User_email_idx" ON "User"("email"); CREATE INDEX "Event_status_eventDate_idx" ON "Event"("status","eventDate"); CREATE INDEX "Event_city_idx" ON "Event"("city"); CREATE INDEX "Event_category_idx" ON "Event"("category"); CREATE INDEX "Event_eventDate_idx" ON "Event"("eventDate"); CREATE INDEX "Event_status_idx" ON "Event"("status"); CREATE INDEX "Event_organizerId_idx" ON "Event"("organizerId"); CREATE INDEX "Booking_userId_idx" ON "Booking"("userId"); CREATE INDEX "Booking_eventId_idx" ON "Booking"("eventId"); CREATE INDEX "Booking_bookingReference_idx" ON "Booking"("bookingReference"); CREATE INDEX "Booking_eventId_status_idx" ON "Booking"("eventId","status"); CREATE INDEX "RefreshToken_userId_idx" ON "RefreshToken"("userId"); CREATE INDEX "RefreshToken_expiresAt_idx" ON "RefreshToken"("expiresAt");
